package io.github.julianperge.modular_planters.ae2;

import appeng.api.AECapabilities;
import io.github.julianperge.modular_planters.registry.MPBlockEntities;
import io.github.julianperge.modular_planters.registry.MPBlocks;
import io.github.julianperge.modular_planters.registry.MPItems;
import net.minecraft.world.item.BlockItem;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.neoforge.capabilities.RegisterCapabilitiesEvent;
import net.neoforged.neoforge.registries.DeferredBlock;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredItem;

public final class Ae2Integration {
    public static final DeferredBlock<MeBlock> ME_BLOCK =
            MPBlocks.BLOCKS.registerBlock("me", MeBlock::new, MPBlocks::metal);
    public static final DeferredItem<BlockItem> ME_ITEM = MPItems.ITEMS.registerSimpleBlockItem(ME_BLOCK);
    public static final DeferredHolder<BlockEntityType<?>, BlockEntityType<MeBlockEntity>> ME_BLOCK_ENTITY =
            MPBlockEntities.TYPES.register("me", () -> new BlockEntityType<>(MeBlockEntity::new, ME_BLOCK.get()));

    private Ae2Integration() {
    }

    // Calling this loads the class, and loading it adds the ME block, its item and its block entity to the mod's registers through the static fields above.
    public static void init(IEventBus modEventBus) {
        modEventBus.addListener(Ae2Integration::registerCapabilities);
    }

    private static void registerCapabilities(RegisterCapabilitiesEvent event) {
        event.registerBlockEntity(AECapabilities.IN_WORLD_GRID_NODE_HOST, ME_BLOCK_ENTITY.get(), (be, side) -> be);
    }
}
package io.github.julianperge.modular_planters.ae2;

import appeng.api.config.Actionable;
import appeng.api.networking.GridFlags;
import appeng.api.networking.GridHelper;
import appeng.api.networking.IGrid;
import appeng.api.networking.IGridNode;
import appeng.api.networking.IInWorldGridNodeHost;
import appeng.api.networking.IManagedGridNode;
import appeng.api.networking.security.IActionHost;
import appeng.api.networking.security.IActionSource;
import appeng.api.stacks.AEItemKey;
import appeng.api.storage.StorageHelper;
import io.github.julianperge.modular_planters.multiblock.MeLink;
import io.github.julianperge.modular_planters.multiblock.MeStatus;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.transfer.item.ItemResource;
import org.jetbrains.annotations.Nullable;

public class MeBlockEntity extends BlockEntity implements MeLink, IInWorldGridNodeHost, IActionHost {
    private final IManagedGridNode mainNode = GridHelper.createManagedNode(this,
                    (MeBlockEntity owner, IGridNode node) -> owner.setChanged())
            .setFlags(GridFlags.REQUIRE_CHANNEL)
            .setInWorldNode(true)
            .setIdlePowerUsage(1.0)
            .setVisualRepresentation(Ae2Integration.ME_ITEM.get());
    private final IActionSource source = IActionSource.ofMachine(this);

    public MeBlockEntity(BlockPos pos, BlockState state) {
        super(Ae2Integration.ME_BLOCK_ENTITY.get(), pos, state);
    }

    public IManagedGridNode mainNode() {
        return mainNode;
    }

    @Override
    public void clearRemoved() {
        super.clearRemoved();
        GridHelper.onFirstTick(this, be -> be.mainNode().create(be.getLevel(), be.getBlockPos()));
    }

    @Override
    public void setRemoved() {
        super.setRemoved();
        mainNode.destroy();
    }

    @Override
    public void onChunkUnloaded() {
        super.onChunkUnloaded();
        mainNode.destroy();
    }

    @Override
    protected void saveAdditional(ValueOutput output) {
        super.saveAdditional(output);
        mainNode.serialize(output);
    }

    @Override
    protected void loadAdditional(ValueInput input) {
        super.loadAdditional(input);
        mainNode.deserialize(input);
    }

    @Override
    public @Nullable IGridNode getGridNode(Direction dir) {
        return mainNode.getNode();
    }

    @Override
    public @Nullable IGridNode getActionableNode() {
        return mainNode.getNode();
    }

    @Override
    public MeStatus status() {
        if (!mainNode.isPowered()) {
            return MeStatus.OFFLINE;
        }
        return mainNode.isActive() ? MeStatus.ONLINE : MeStatus.NO_CHANNEL;
    }

    @Override
    public long insertItem(ItemResource resource, long amount, boolean simulate) {
        AEItemKey key = AEItemKey.of(resource);
        IGrid grid = mainNode.getGrid();
        if (key == null || grid == null || !mainNode.isActive()) {
            return 0;
        }
        return StorageHelper.poweredInsert(grid.getEnergyService(), grid.getStorageService().getInventory(), key,
                amount, source, simulate ? Actionable.SIMULATE : Actionable.MODULATE);
    }

    @Override
    public long extractItem(ItemResource resource, long amount, boolean simulate) {
        AEItemKey key = AEItemKey.of(resource);
        IGrid grid = mainNode.getGrid();
        if (key == null || grid == null || !mainNode.isActive()) {
            return 0;
        }
        return StorageHelper.poweredExtraction(grid.getEnergyService(), grid.getStorageService().getInventory(), key,
                amount, source, simulate ? Actionable.SIMULATE : Actionable.MODULATE);
    }

    @Override
    public long extractEnergy(long amount, boolean simulate) {
        return 0;
    }

    @Override
    public ItemResource fertilizerFilter() {
        return ItemResource.EMPTY;
    }
}
package io.github.julianperge.modular_planters.gametest;

import appeng.api.networking.IGrid;
import appeng.api.stacks.AEItemKey;
import io.github.julianperge.modular_planters.ae2.Ae2Integration;
import io.github.julianperge.modular_planters.ae2.MeBlockEntity;
import io.github.julianperge.modular_planters.blockentity.CoreBlockEntity;
import io.github.julianperge.modular_planters.blockentity.ExportBlockEntity;
import io.github.julianperge.modular_planters.logic.Problem;
import io.github.julianperge.modular_planters.multiblock.MeStatus;
import java.util.Map;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.block.Blocks;

public final class Ae2Tests {
    private Ae2Tests() {
    }

    public static void register(Map<String, TestCase> into) {
        into.put("me_block_joins_the_grid", new TestCase(100, Ae2Tests::meBlockJoinsTheGrid));
        into.put("export_contents_move_into_me", new TestCase(100, Ae2Tests::exportContentsMoveIntoMe));
        into.put("me_offline_falls_back_to_export", new TestCase(200, Ae2Tests::meOfflineFallsBackToExport));
        into.put("breaking_me_block_falls_back_to_export",
                new TestCase(200, Ae2Tests::breakingMeBlockFallsBackToExport));
        into.put("second_me_block_stops_forming", new TestCase(40, Ae2Tests::secondMeBlockStopsForming));
    }

    private static long meCount(GameTestHelper helper, MeBlockEntity me, Item item) {
        IGrid grid = me.mainNode().getGrid();
        helper.assertTrue(grid != null, "the ME block has a grid");
        return grid.getStorageService().getInventory().getAvailableStacks().get(AEItemKey.of(item));
    }

    private static void meBlockJoinsTheGrid(GameTestHelper helper) {
        Fixtures.Rig rig = Fixtures.meRig(helper, 1);
        CoreBlockEntity core = helper.getBlockEntity(rig.core(), CoreBlockEntity.class);
        helper.succeedWhen(() -> helper.assertValueEqual(core.meStatus(), MeStatus.ONLINE, "ME status"));
    }

    private static void exportContentsMoveIntoMe(GameTestHelper helper) {
        Fixtures.Rig rig = Fixtures.meRig(helper, 1);
        ExportBlockEntity export = helper.getBlockEntity(rig.export(), ExportBlockEntity.class);
        MeBlockEntity me = helper.getBlockEntity(Fixtures.ME, MeBlockEntity.class);
        MeLinkTests.fill(export, Items.WHEAT, 64);
        helper.succeedWhen(() -> {
            helper.assertValueEqual(MeLinkTests.count(export, Items.WHEAT), 0, "wheat in export");
            helper.assertValueEqual(meCount(helper, me, Items.WHEAT), 64L, "wheat in ME");
        });
    }

    private static void meOfflineFallsBackToExport(GameTestHelper helper) {
        Fixtures.Rig rig = Fixtures.meRig(helper, 1);
        CoreBlockEntity core = helper.getBlockEntity(rig.core(), CoreBlockEntity.class);
        ExportBlockEntity export = helper.getBlockEntity(rig.export(), ExportBlockEntity.class);
        helper.startSequence()
                .thenWaitUntil(() -> helper.assertValueEqual(core.meStatus(), MeStatus.ONLINE, "ME status"))
                .thenExecute(() -> helper.setBlock(Fixtures.ENERGY_CELL, Blocks.AIR))
                .thenWaitUntil(() -> helper.assertTrue(core.meStatus() != MeStatus.ONLINE, "ME went offline"))
                .thenExecute(() -> {
                    helper.assertTrue(core.outputs().insert(new ItemStack(Items.WHEAT, 64)).isEmpty(),
                            "nothing left over");
                    helper.assertValueEqual(MeLinkTests.count(export, Items.WHEAT), 64, "wheat in export");
                })
                .thenSucceed();
    }

    private static void breakingMeBlockFallsBackToExport(GameTestHelper helper) {
        Fixtures.Rig rig = Fixtures.meRig(helper, 1);
        CoreBlockEntity core = helper.getBlockEntity(rig.core(), CoreBlockEntity.class);
        ExportBlockEntity export = helper.getBlockEntity(rig.export(), ExportBlockEntity.class);
        helper.startSequence()
                .thenWaitUntil(() -> helper.assertValueEqual(core.meStatus(), MeStatus.ONLINE, "ME status"))
                .thenExecute(() -> helper.getLevel().destroyBlock(helper.absolutePos(Fixtures.ME), true))
                .thenExecuteAfter(1, () -> {
                    helper.assertTrue(core.lastScan().formed(), "still formed");
                    helper.assertValueEqual(core.meStatus(), MeStatus.NONE, "ME status");
                    helper.assertTrue(core.outputs().insert(new ItemStack(Items.WHEAT, 64)).isEmpty(),
                            "nothing left over");
                    helper.assertValueEqual(MeLinkTests.count(export, Items.WHEAT), 64, "wheat in export");
                })
                .thenSucceed();
    }

    private static void secondMeBlockStopsForming(GameTestHelper helper) {
        Fixtures.Rig rig = Fixtures.meRig(helper, 1);
        helper.setBlock(new BlockPos(3, 2, 1), Ae2Integration.ME_BLOCK.get());
        CoreBlockEntity core = helper.getBlockEntity(rig.core(), CoreBlockEntity.class);
        helper.succeedWhen(() -> helper.assertValueEqual(core.lastScan().problem(), Problem.SECOND_ME, "problem"));
    }
}
package io.github.julianperge.modular_planters.gametest;

import com.mojang.serialization.Codec;
import com.mojang.serialization.MapCodec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import io.github.julianperge.modular_planters.ModularPlanters;
import java.util.LinkedHashMap;
import java.util.Map;
import net.minecraft.core.Holder;
import net.minecraft.core.registries.Registries;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.gametest.framework.GameTestInstance;
import net.minecraft.gametest.framework.TestData;
import net.minecraft.gametest.framework.TestEnvironmentDefinition;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.resources.Identifier;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.fml.ModList;
import net.neoforged.neoforge.event.RegisterGameTestsEvent;
import net.neoforged.neoforge.registries.DeferredRegister;

public final class MPTestRegistration {
    public static final Identifier STRUCTURE = id("empty");

    // The mod constructor loads this class before any registry is filled, which runs every tests class's register method and static fields, so a tests class must call get() on mod registry objects only inside its test methods.
    private static final Map<String, TestCase> CASES = cases();

    private MPTestRegistration() {
    }

    private static Map<String, TestCase> cases() {
        Map<String, TestCase> cases = new LinkedHashMap<>();
        RecipeTests.register(cases);
        StructureTests.register(cases);
        StorageTests.register(cases);
        DoorwayTests.register(cases);
        AteBridgeTests.register(cases);
        PlanterTests.register(cases);
        PlanterLifecycleTests.register(cases);
        MenuTests.register(cases);
        CoreScreenTests.register(cases);
        MeLinkTests.register(cases);
        if (ModList.get().isLoaded("ae2")) {
            Ae2Tests.register(cases);
        }
        return cases;
    }

    public static void register(IEventBus modEventBus) {
        DeferredRegister<MapCodec<? extends GameTestInstance>> instanceTypes =
                DeferredRegister.create(Registries.TEST_INSTANCE_TYPE, ModularPlanters.MOD_ID);
        instanceTypes.register("case", () -> CaseInstance.CODEC);
        instanceTypes.register(modEventBus);
        modEventBus.addListener(MPTestRegistration::registerTests);
    }

    private static void registerTests(RegisterGameTestsEvent event) {
        Holder<TestEnvironmentDefinition<?>> environment = event.registerEnvironment(id("default"));
        CASES.forEach((name, testCase) -> event.registerTest(id(name),
                new CaseInstance(name, new TestData<>(environment, STRUCTURE, testCase.maxTicks(), 0, true))));
    }

    private static Identifier id(String path) {
        return Identifier.fromNamespaceAndPath(ModularPlanters.MOD_ID, path);
    }

    private static final class CaseInstance extends GameTestInstance {
        static final MapCodec<CaseInstance> CODEC = RecordCodecBuilder.mapCodec(instance -> instance.group(
                Codec.STRING.fieldOf("case").forGetter(test -> test.name),
                TestData.CODEC.forGetter(CaseInstance::info)
        ).apply(instance, CaseInstance::new));

        private final String name;

        CaseInstance(String name, TestData<Holder<TestEnvironmentDefinition<?>>> data) {
            super(data);
            this.name = name;
        }

        @Override
        public void run(GameTestHelper helper) {
            CASES.get(name).body().accept(helper);
        }

        @Override
        public MapCodec<CaseInstance> codec() {
            return CODEC;
        }

        @Override
        protected MutableComponent typeDescription() {
            return Component.literal("Modular Planters case");
        }
    }
}

