package io.github.julianperge.modular_planters.multiblock;

import io.github.julianperge.modular_planters.blockentity.PowerBlockEntity;
import net.neoforged.neoforge.transfer.energy.EnergyHandler;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;

import java.util.List;

public final class PowerPool {
    private final List<PowerBlockEntity> blocks;
    private final Runnable onStale;
    private final EnergyHandler insertView = new InsertView();

    public PowerPool(List<PowerBlockEntity> inOrder, Runnable onStale) {
        this.blocks = List.copyOf(inOrder);
        this.onStale = onStale;
    }

    private List<PowerBlockEntity> live() {
        return LiveBlocks.of(blocks, onStale);
    }

    public long stored() {
        long total = 0;
        for (PowerBlockEntity block : live()) {
            total += block.stored();
        }
        return total;
    }

    public long capacity() {
        long total = 0;
        for (PowerBlockEntity block : live()) {
            total += block.capacity();
        }
        return total;
    }

    public boolean tryTake(long amount) {
        if (amount < 0 || stored() < amount) {
            return false;
        }
        long remaining = amount;
        for (PowerBlockEntity block : live()) {
            int taken = (int) Math.min(remaining, block.stored());
            if (taken > 0) {
                block.setStored(block.stored() - taken);
                remaining -= taken;
            }
        }
        return true;
    }

    public long refillFrom(MeLink me, long wanted) {
        if (!me.online()) {
            return 0;
        }
        List<PowerBlockEntity> live = live();
        long room = 0;
        for (PowerBlockEntity block : live) {
            room += Math.max(0, block.capacity() - block.stored());
        }
        long asked = Math.min(wanted, room);
        if (asked <= 0) {
            return 0;
        }
        long moved = me.extractEnergy(asked, false);
        long remaining = moved;
        for (PowerBlockEntity block : live) {
            int added = (int) Math.min(remaining, Math.max(0, block.capacity() - block.stored()));
            if (added > 0) {
                block.setStored(block.stored() + added);
                remaining -= added;
            }
        }
        return moved;
    }

    public EnergyHandler insertView() {
        return insertView;
    }

    private final class InsertView implements EnergyHandler {
        @Override
        public long getAmountAsLong() {
            return stored();
        }

        @Override
        public long getCapacityAsLong() {
            return capacity();
        }

        @Override
        public int insert(int amount, TransactionContext transaction) {
            int inserted = 0;
            for (PowerBlockEntity block : live()) {
                if (inserted == amount) {
                    break;
                }
                inserted += block.externalHandler().insert(amount - inserted, transaction);
            }
            return inserted;
        }

        @Override
        public int extract(int amount, TransactionContext transaction) {
            return 0;
        }
    }
}
package io.github.julianperge.modular_planters.multiblock;

import net.neoforged.neoforge.transfer.item.ItemResource;

public interface MeLink {
    MeStatus status();

    long insertItem(ItemResource resource, long amount, boolean simulate);

    long extractItem(ItemResource resource, long amount, boolean simulate);

    long extractEnergy(long amount, boolean simulate);

    ItemResource fertilizerFilter();

    boolean isRemoved();

    default boolean online() {
        return status() == MeStatus.ONLINE;
    }
}

public class CoreBlockEntity extends BlockEntity {
    private static final int RESCAN_INTERVAL = 20;

    private ScanResult<BlockPos> lastScan = new ScanResult<>(Problem.WAITING_FOR_CHUNKS, null, Map.of());
    private @Nullable Multiblock multiblock;
    private @Nullable PowerPool power;
    private @Nullable FertilizerPool fertilizer;
    private @Nullable OutputSink outputs;
    private @Nullable MeLink me;
    private boolean dirty = true;
    private boolean poolsStale;
    private long wantedLastTick;

    public CoreBlockEntity(BlockPos pos, BlockState state) {
        super(MPBlockEntities.CORE.get(), pos, state);
    }

    public static void serverTick(Level level, BlockPos pos, BlockState state, CoreBlockEntity core) {
        if (core.dirty || level.getGameTime() % RESCAN_INTERVAL == 0) {
            core.scan(level);
        }
        if (level instanceof ServerLevel serverLevel) {
            core.tickPlanters(serverLevel);
        }
    }

    // The pools are null while the core waits for an unloaded chunk, and the planters then keep their progress without ticking.
    private void tickPlanters(ServerLevel level) {
        if (multiblock == null || power == null || fertilizer == null || outputs == null || !allPartsLoaded()) {
            wantedLastTick = 0;
            return;
        }
        MeLink link = onlineMe();
        if (link != null && wantedLastTick > 0) {
            power.refillFrom(link, wantedLastTick);
        }
        TickContext context = new TickContext(level, level.getRandom(), AteBridge.numbers(), power, fertilizer.budget(), outputs);
        long wanted = 0;
        for (BlockPos pos : multiblock.planters()) {
            if (level.getBlockEntity(pos) instanceof PlanterBlockEntity planter) {
                planter.tickFromCore(context);
                wanted += planter.lastWanted();
            }
        }
        wantedLastTick = wanted;
        if (link != null && level.getGameTime() % MPConfig.ME_INTERVAL.get() == 0) {
            outputs.moveExportsInto(link);
            fertilizer.topUpFrom(link);
        }
    }

    // This returns the link only while it is online, and a removed link counts as absent and marks the pools stale so the next scan rebuilds them without it.
    private @Nullable MeLink onlineMe() {
        if (me == null) {
            return null;
        }
        if (me.isRemoved()) {
            markPoolsStale();
            return null;
        }
        return me.online() ? me : null;
    }

    public void markDirty() {
        dirty = true;
    }

    // A pooled block was removed, and a replacement at the same position gives an equal scan result, so the next scan must rebuild the pools anyway.
    private void markPoolsStale() {
        dirty = true;
        poolsStale = true;
    }

    public ScanResult<BlockPos> lastScan() {
        return lastScan;
    }

    public @Nullable Multiblock multiblock() {
        return multiblock;
    }

    public @Nullable PowerPool power() {
        return power;
    }

    public @Nullable FertilizerPool fertilizer() {
        return fertilizer;
    }

    public @Nullable OutputSink outputs() {
        return outputs;
    }

    public MeStatus meStatus() {
        return me == null || me.isRemoved() ? MeStatus.NONE : me.status();
    }

    public boolean allPartsLoaded() {
        return level != null && (multiblock == null || multiblock.all().stream().allMatch(level::isLoaded));
    }

